const pptxgen = require('pptxgenjs');
const fs = require('fs');
const path = require('path');

const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

const theme = {
  primary: "0f172a",    // Slate 900
  secondary: "334155",  // Slate 700
  accent: "0284c7",     // Sky 600
  light: "e0f2fe",      // Sky 100
  bg: "f8fafc"          // Slate 50
};

// Add standard badge layout logic to be used by slides if they want, 
// though the instructions say each slide should add it individually.
for (let i = 1; i <= 8; i++) {
  const num = String(i).padStart(2, '0');
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

// Ensure output dir exists
const outputDir = '/app/output';
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

pres.writeFile({ fileName: '/app/output/final_deck.pptx' })
  .then(() => console.log("Created /app/output/final_deck.pptx"))
  .catch(err => console.error(err));

