const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'KnowSelf: Agentic Knowledgeable Self-Awareness for LLM-Based Agents'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Decorative shapes
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.5, h: "100%", fill: { color: theme.accent }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0, w: 0.2, h: "100%", fill: { color: theme.light }
  });

  // Main Title
  slide.addText(slideConfig.title, {
    x: 1.5, y: 1.8, w: 7.5, h: 1.5,
    fontSize: 44, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left",
    valign: "bottom"
  });

  // Subtitle / Tagline
  slide.addText("Enabling agents to autonomously regulate knowledge utilization through situational self-awareness.", {
    x: 1.5, y: 3.5, w: 7.5, h: 1.0,
    fontSize: 24, fontFace: "Arial",
    color: theme.secondary, bold: false, align: "left",
    valign: "top"
  });

  // Source / Metadata
  slide.addText("Paper: arxiv.org/abs/2504.03553", {
    x: 1.5, y: 4.8, w: 7.5, h: 0.5,
    fontSize: 16, fontFace: "Arial",
    color: theme.accent, bold: true, align: "left"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

