const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 2,
  title: "Current Agent Training Uses 'Flood Irrigation'"
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Page Badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  // Slide Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.4, w: 9, h: 0.6,
    fontSize: 36, fontFace: "Arial", color: theme.primary, bold: true
  });

  // Subtitle
  slide.addText("Indiscriminate Knowledge Injection Hurts Efficiency", {
    x: 0.5, y: 1.0, w: 9, h: 0.4,
    fontSize: 20, fontFace: "Arial", color: theme.accent, bold: true
  });

  // Main Problem Statement
  slide.addText("Existing approaches blindly inject gold trajectories, external feedback, and domain knowledge without considering situational needs. This limits efficiency and leads to pattern collapse.", {
    x: 0.5, y: 1.6, w: 9, h: 0.6,
    fontSize: 16, fontFace: "Arial", color: theme.secondary
  });

  // Comparison Boxes
  const boxY = 2.5;
  const boxW = 2.8;
  const boxH = 2.0;

  // Box 1
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: boxY, w: boxW, h: boxH, fill: { color: theme.light }, rectRadius: 0.1
  });
  slide.addText("Trajectory Imitation", {
    x: 0.5, y: boxY + 0.1, w: boxW, h: 0.4, align: "center",
    fontSize: 18, fontFace: "Arial", color: theme.primary, bold: true
  });
  slide.addText("e.g., ReAct\n\nBlindly mimics successful paths. Often fails on unexpected variations.", {
    x: 0.7, y: boxY + 0.6, w: boxW - 0.4, h: 1.2, align: "left", valign: "top",
    fontSize: 14, fontFace: "Arial", color: theme.secondary
  });

  // Box 2
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 3.6, y: boxY, w: boxW, h: boxH, fill: { color: theme.light }, rectRadius: 0.1
  });
  slide.addText("Trial-and-Error", {
    x: 3.6, y: boxY + 0.1, w: boxW, h: 0.4, align: "center",
    fontSize: 18, fontFace: "Arial", color: theme.primary, bold: true
  });
  slide.addText("e.g., Reflexion\n\nRelies heavily on environment feedback to refine paths. High inference cost.", {
    x: 3.8, y: boxY + 0.6, w: boxW - 0.4, h: 1.2, align: "left", valign: "top",
    fontSize: 14, fontFace: "Arial", color: theme.secondary
  });

  // Box 3
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 6.7, y: boxY, w: boxW, h: boxH, fill: { color: theme.light }, rectRadius: 0.1
  });
  slide.addText("Knowledge-Augmented", {
    x: 6.7, y: boxY + 0.1, w: boxW, h: 0.4, align: "center",
    fontSize: 18, fontFace: "Arial", color: theme.primary, bold: true
  });
  slide.addText("e.g., KnowAgent, WKM\n\nInjects knowledge unconditionally at every step. Wasteful and fragile.", {
    x: 6.9, y: boxY + 0.6, w: boxW - 0.4, h: 1.2, align: "left", valign: "top",
    fontSize: 14, fontFace: "Arial", color: theme.secondary
  });

  // Contrast Statement
  slide.addText("In contrast, humans possess situational self-awareness: assessing whether to act directly, pause, or seek help.", {
    x: 0.5, y: 4.8, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Arial", color: theme.primary, bold: true, italic: true
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

