const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 3,
  title: 'Three Situational Modes'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Page Badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  // Slide Title
  slide.addText("Three Situational Modes", {
    x: 0.5, y: 0.4, w: 9, h: 0.6,
    fontSize: 36, fontFace: "Arial", color: theme.primary, bold: true
  });

  // Subtitle
  slide.addText("Fast Thinking, Slow Thinking, and Knowledgeable Thinking", {
    x: 0.5, y: 1.0, w: 9, h: 0.4,
    fontSize: 20, fontFace: "Arial", color: theme.accent, bold: true
  });

  // Decision Tree / Flow diagram
  const startX = 0.5;
  const colW = 2.5;

  // Node 1: Start
  slide.addShape(pres.shapes.DIAMOND, {
    x: 3.5, y: 1.6, w: 2.5, h: 1.2, fill: { color: theme.light }
  });
  slide.addText("Can agent produce\ncorrect action directly?", {
    x: 3.5, y: 1.6, w: 2.5, h: 1.2, align: "center", valign: "middle",
    fontSize: 14, fontFace: "Arial", color: theme.primary, bold: true
  });

  // Arrow Yes
  slide.addShape(pres.shapes.RIGHT_ARROW, {
    x: 2.3, y: 2.0, w: 1.2, h: 0.2, fill: { color: theme.secondary }, rotate: 180
  });
  slide.addText("Yes", { x: 2.6, y: 1.7, w: 0.6, h: 0.3, fontSize: 12, color: theme.primary, bold: true });

  // Fast Thinking Result
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 1.7, w: colW, h: 0.8, fill: { color: theme.bg }, line: { color: theme.accent, width: 2 }
  });
  slide.addText("Fast Thinking\nDirect correct action", {
    x: 0.5, y: 1.7, w: colW, h: 0.8, align: "center", valign: "middle",
    fontSize: 14, fontFace: "Arial", color: theme.primary, bold: true
  });

  // Arrow No (down)
  slide.addShape(pres.shapes.DOWN_ARROW, {
    x: 4.65, y: 2.8, w: 0.2, h: 0.8, fill: { color: theme.secondary }
  });
  slide.addText("No", { x: 4.8, y: 2.9, w: 0.6, h: 0.3, fontSize: 12, color: theme.primary, bold: true });

  // Node 2: Reflection
  slide.addShape(pres.shapes.DIAMOND, {
    x: 3.5, y: 3.6, w: 2.5, h: 1.2, fill: { color: theme.light }
  });
  slide.addText("Can agent self-correct\nthrough reflection?", {
    x: 3.5, y: 3.6, w: 2.5, h: 1.2, align: "center", valign: "middle",
    fontSize: 14, fontFace: "Arial", color: theme.primary, bold: true
  });

  // Arrow Yes (from Reflection)
  slide.addShape(pres.shapes.RIGHT_ARROW, {
    x: 2.3, y: 4.0, w: 1.2, h: 0.2, fill: { color: theme.secondary }, rotate: 180
  });
  slide.addText("Yes", { x: 2.6, y: 3.7, w: 0.6, h: 0.3, fontSize: 12, color: theme.primary, bold: true });

  // Slow Thinking Result
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 3.7, w: colW, h: 0.8, fill: { color: theme.bg }, line: { color: theme.accent, width: 2 }
  });
  slide.addText("Slow Thinking\nCorrect after reflection", {
    x: 0.5, y: 3.7, w: colW, h: 0.8, align: "center", valign: "middle",
    fontSize: 14, fontFace: "Arial", color: theme.primary, bold: true
  });

  // Arrow No (right from Reflection)
  slide.addShape(pres.shapes.RIGHT_ARROW, {
    x: 6.0, y: 4.0, w: 1.0, h: 0.2, fill: { color: theme.secondary }
  });
  slide.addText("No", { x: 6.2, y: 3.7, w: 0.6, h: 0.3, fontSize: 12, color: theme.primary, bold: true });

  // Knowledgeable Thinking Result
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 7.0, y: 3.6, w: 2.5, h: 1.2, fill: { color: theme.accent }
  });
  slide.addText("Knowledgeable\nThinking\nConsult external\nknowledge base", {
    x: 7.0, y: 3.6, w: 2.5, h: 1.2, align: "center", valign: "middle",
    fontSize: 14, fontFace: "Arial", color: "FFFFFF", bold: true
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

