    x: 0.5, y: 1.0, w: 9, h: 0.4,
    fontSize: 20, fontFace: "Arial", color: theme.accent, bold: true
  });

  // Chart data: KnowSelf vs KnowAgent vs WKM
  const arrDataRegions = [
    {
      name: "Knowledge Usage %",
      labels: ["GPT-4o ExpeL", "Llama-8B WKM", "Llama-8B KnowAgent", "Llama-8B KnowSelf", "Gemma-2B KnowSelf"],
      values: [100, 100, 100, 15.01, 26.41]
