    {
      name: "Accuracy %",
      labels: ["GPT-4o ExpeL", "Llama-8B WKM", "Llama-8B KnowAgent", "Llama-8B KnowSelf", "Gemma-2B KnowSelf"],
      values: [79.85, 77.61, 75.37, 84.33, 79.85]
    }
  ];

  // Bar Chart
  slide.addChart(pres.charts.BAR, arrDataRegions, {
    x: 0.5, y: 1.6, w: 5.0, h: 3.2,
    barDir: "col",
    barGrouping: "clustered",
    showLegend: true, legendPos: "b",
    chartColors: [theme.secondary, theme.accent],
    showValue: true,
    dataLabelFormatCode: "0.#",
    dataLabelColor: theme.primary,
    dataLabelFontFace: "Arial",
    dataLabelFontSize: 10,
    dataLabelPosition: "outEnd",
    catAxisLabelFontSize: 10,
    valAxisMinVal: 0, valAxisMaxVal: 110,
    gridLineColor: theme.light
  });

  // Text takeaways on the right
  const textX = 5.8;
  const textW = 3.6;

  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: textX, y: 1.6, w: textW, h: 1.4, fill: { color: theme.light }, rectRadius: 0.1
  });
  slide.addText("Efficiency Advantage", {
    x: textX + 0.2, y: 1.7, w: textW - 0.4, h: 0.4,
    fontSize: 18, fontFace: "Arial", color: theme.primary, bold: true
  });
  slide.addText("KnowSelf uses only ~15% to 26% knowledge queries compared to 100% for KnowAgent, WKM, and ExpeL, yet achieves the highest overall scores.", {
    x: textX + 0.2, y: 2.1, w: textW - 0.4, h: 0.8,
    fontSize: 14, fontFace: "Arial", color: theme.secondary, align: "left", valign: "top"
  });

  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: textX, y: 3.2, w: textW, h: 1.4, fill: { color: theme.light }, rectRadius: 0.1
  });
  slide.addText("Model Scaling Behavior", {
    x: textX + 0.2, y: 3.3, w: textW - 0.4, h: 0.4,
    fontSize: 18, fontFace: "Arial", color: theme.primary, bold: true
  });
  slide.addText("The approach generalizes across scales. Even the smaller Gemma-2B model reaches 79.85% matching GPT-4o ExpeL.", {
    x: textX + 0.2, y: 3.7, w: textW - 0.4, h: 0.8,
    fontSize: 14, fontFace: "Arial", color: theme.secondary, align: "left", valign: "top"
  });

  return slide;
}

